<script setup lang="ts">
/**
 * A side pane that shows one artifact a turn produced (`design/components/artifact-pane.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/artifact-pane.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  useId,
  useTemplateRef,
  watch,
  type VNode,
} from 'vue'

import { Icon, agentMember, useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/artifact-pane.module.css'
import Button from '../controls/Button.vue'
import SegmentedControl from '../controls/SegmentedControl.vue'
import Spinner from '../structure/Spinner.vue'

export type ArtifactKind = 'code' | 'document' | 'data' | 'preview'

export interface ArtifactView {
  id: string
  label: string
  content: VNode | string
}

export interface ArtifactPaneProps {
  /**
   * The close button's accessible name (generic default `Close`), which localized hosts replace.
   */
  closeLabel?: string
  defaultView?: string
  /**
   * The artifact's kind, which picks the mark (the tier's `artifact` glyph when absent).
   */
  kind?: 'document' | 'code' | 'data' | 'preview'
  /**
   * One preformatted line under the title, such as "TypeScript · 142 lines".
   */
  meta?: string
  /**
   * Whether the artifact is still being written, which shows a spinner and sets `aria-busy`.
   */
  streaming?: boolean
  /**
   * The artifact's name, used as the pane's heading and accessible name.
   */
  title: string
  view?: string
  /**
   * The artifact's views (code, preview). Two or more draw a switch, and a single view is drawn
   * with no switch. When `views` is absent or empty, `children` is the body.
   */
  views?: ArtifactView[]
  /**
   * The switch's accessible name (generic default `View`).
   */
  viewsLabel?: string
}

defineOptions({ name: 'ArtifactPane', inheritAttrs: false })

const props = withDefaults(defineProps<ArtifactPaneProps>(), {
  closeLabel: 'Close',
  streaming: false,
  viewsLabel: 'View',
})
const emit = defineEmits<{ close: []; viewChange: [id: string] }>()
defineSlots<{
  actions?: (props: Record<string, never>) => unknown
  default?: (props: Record<string, never>) => unknown
}>()
const uid = useId()
const listening = useListening()
const overflowing = ref(false)
const mirror = ref(props.defaultView ?? props.views?.[0]?.id)
const body = useTemplateRef<HTMLElement>('body')
const closer = useTemplateRef<HTMLElement>('closer')
const pane = useTemplateRef<HTMLElement>('pane')
const switcher = useTemplateRef<HTMLElement>('switcher')
const titleId = computed(() => `${uid}-title`)
const current = computed(() => props.view ?? mirror.value)
const switching = computed(() => props.views !== undefined && props.views.length > 1)
const shown = computed(() =>
  props.views === undefined
    ? undefined
    : (props.views.find((entry) => entry.id === current.value) ?? props.views[0]),
)
const mark = computed(() =>
  props.kind === undefined
    ? 'artifact'
    : ({ code: 'terminal', document: 'document', data: 'table', preview: 'browser' } as const)[
        props.kind
      ],
)
const choices = computed(() =>
  (props.views ?? []).map((entry) => ({ value: entry.id, label: entry.label })),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    overflowing.value = body.value !== null && body.value.scrollHeight > body.value.clientHeight
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [body.value, body.value?.firstElementChild])
    if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect1)
watch(() => shown.value?.id, effect1, { flush: 'post' })
onBeforeUnmount(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'ArtifactPane',
    element: () => pane.value,
    state: () => ({
      view: shown.value?.id ?? null,
      views: (props.views ?? []).map((entry) => ({ id: entry.id, label: entry.label })),
      streaming: props.streaming,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          value !== shown.value?.id && ((mirror.value = value), emit('viewChange', value)),
      },
      close: () =>
        (() => {
          if (!listening.close) throw new Error('The pane has no close control.')
          emit('close')
        })(),
    },
    withholds: () => [switcher.value, closer.value],
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <section
    ref="pane"
    :class="styles.pane"
    :aria-labelledby="titleId"
    :data-kind="kind"
    :data-state="streaming ? 'streaming' : undefined"
    :aria-busy="streaming ? true : undefined"
    data-member="artifact-pane"
  >
    <header :class="styles.header">
      <span :class="styles.mark">
        <Spinner v-if="streaming" size="sm" :label="`${title}: still being written`" />
        <Icon v-else :name="mark" size="sm" />
      </span>
      <div :class="styles.heading">
        <h2 :class="styles.title" :id="titleId">
          {{ title }}
        </h2>
        <p v-if="meta !== undefined" :class="styles.meta">
          {{ meta }}
        </p>
      </div>
      <div v-if="switching" ref="switcher" :class="styles.views">
        <SegmentedControl
          size="sm"
          :label="viewsLabel"
          :options="choices"
          :value="current"
          @change="((mirror = $event), emit('viewChange', $event))"
        />
      </div>
      <div v-if="$slots.actions" :class="styles.actions">
        <slot name="actions" />
      </div>
      <div v-if="listening.close" ref="closer" :class="styles.close">
        <Button
          variant="ghost"
          tone="neutral"
          size="sm"
          :iconOnly="true"
          icon="close"
          :label="closeLabel"
          @click="emit('close')"
        />
      </div>
    </header>
    <div
      ref="body"
      :class="styles.body"
      :data-view="shown?.id"
      :tabindex="overflowing ? 0 : undefined"
      :role="overflowing ? 'group' : undefined"
      :aria-labelledby="overflowing ? titleId : undefined"
    >
      <div :class="styles.content">
        <template v-if="shown === undefined">
          <slot />
        </template>
        <template v-else-if="typeof shown.content === 'string'">{{ shown.content }}</template>
        <template v-else>
          <component :is="shown.content" />
        </template>
      </div>
    </div>
  </section>
</template>
